// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title FileProxyRegistry
 * @notice Manages user-uploaded content routing through a decentralized proxy network
 * @dev Stores content metadata and resolves paths for the off-chain proxy layer
 */
contract FileProxyRegistry is Ownable {
    using Strings for uint256;

    struct ContentEntry {
        address uploader;
        bytes32 contentHash;
        string resolvedPath;
        uint256 timestamp;
        bool active;
    }

    mapping(bytes32 => ContentEntry) public registry;
    mapping(address => bytes32[]) public userUploads;

    // Allowed base directories for content resolution
    string[] public allowedBases;

    // Path segment separator - used in normalization
    bytes1 private constant SEPARATOR = 0x2f;
    // Parent directory marker length
    uint8 private constant PARENT_SEQ_LEN = 3;

    event ContentRegistered(bytes32 indexed id, address indexed uploader, string path);
    event ContentDeactivated(bytes32 indexed id);
    event BaseAdded(string base);

    constructor() Ownable() {
        allowedBases.push("/data/uploads/");
        allowedBases.push("/data/public/");
    }

    function addAllowedBase(string calldata base) external onlyOwner {
        allowedBases.push(base);
        emit BaseAdded(base);
    }

    /**
     * @notice Register content with a user-specified relative path
     * @param relativePath The relative path within the allowed base
     * @param contentHash The hash of the uploaded content
     * @param baseIndex Index into allowedBases array
     */
    function registerContent(
        string calldata relativePath,
        bytes32 contentHash,
        uint256 baseIndex
    ) external returns (bytes32) {
        require(baseIndex < allowedBases.length, "Invalid base index");
        require(bytes(relativePath).length > 0, "Empty path");
        require(bytes(relativePath).length <= 256, "Path too long");

        // Sanitize the relative path
        string memory sanitized = _sanitizePath(relativePath);

        // Build the full resolved path
        string memory fullPath = string(abi.encodePacked(
            allowedBases[baseIndex],
            sanitized
        ));

        bytes32 entryId = keccak256(abi.encodePacked(
            msg.sender,
            contentHash,
            block.timestamp
        ));

        // Prevent silent overwrite / duplicate registration on entryId collision
        require(registry[entryId].uploader == address(0), "Entry already exists");

        registry[entryId] = ContentEntry({
            uploader: msg.sender,
            contentHash: contentHash,
            resolvedPath: fullPath,
            timestamp: block.timestamp,
            active: true
        });

        userUploads[msg.sender].push(entryId);
        emit ContentRegistered(entryId, msg.sender, fullPath);

        return entryId;
    }

    function deactivateContent(bytes32 entryId) external {
        require(
            registry[entryId].uploader == msg.sender || msg.sender == owner(),
            "Not authorized"
        );
        registry[entryId].active = false;
        emit ContentDeactivated(entryId);
    }

    function getResolvedPath(bytes32 entryId) external view returns (string memory) {
        require(registry[entryId].active, "Content not active");
        return registry[entryId].resolvedPath;
    }

    /**
     * @dev Sanitizes a relative path by removing traversal sequences
     * Uses iterative scanning to handle nested/encoded traversals
     */
    function _sanitizePath(string calldata path) internal pure returns (string memory) {
        bytes memory input = bytes(path);
        bytes memory output = new bytes(input.length);
        uint256 outLen = 0;

        uint256 i = 0;
        while (i < input.length) {
            // Check for path traversal: "../"
            if (i + 2 < input.length && 
                input[i] == 0x2e &&      // '.'
                input[i+1] == 0x2e &&     // '.'
                input[i+2] == SEPARATOR)  // '/'
            {
                // Skip the traversal sequence
                i += PARENT_SEQ_LEN;
                continue;
            }

            // Check for standalone ".." at end of path (no trailing slash)
            if (i + 1 < input.length && i + 2 >= input.length &&
                input[i] == 0x2e &&
                input[i+1] == 0x2e)
            {
                i += 2;
                continue;
            }

            // Check for encoded dot sequences: %2e%2e%2f
            if (i + 8 < input.length &&
                input[i] == 0x25 &&       // '%'
                (input[i+1] == 0x32) &&   // '2'
                (input[i+2] == 0x65 || input[i+2] == 0x45) && // 'e' or 'E'
                input[i+3] == 0x25 &&     // '%'
                (input[i+4] == 0x32) &&   // '2'
                (input[i+5] == 0x65 || input[i+5] == 0x45) && // 'e' or 'E'
                input[i+6] == 0x25 &&     // '%'
                (input[i+7] == 0x32) &&   // '2'
                (input[i+8] == 0x66 || input[i+8] == 0x46))   // 'f' or 'F'
            {
                i += 9;
                continue;
            }

            // Check for null bytes
            if (input[i] == 0x00) {
                i++;
                continue;
            }

            // Reject any remaining dot-dot patterns (belt and suspenders)
            if (input[i] == 0x2e && i + 1 < input.length && input[i+1] == 0x2e) {
                i += 2;
                continue;
            }

            output[outLen] = input[i];
            outLen++;
            i++;
        }

        // Trim output to actual length
        bytes memory result = new bytes(outLen);
        for (uint256 j = 0; j < outLen; j++) {
            result[j] = output[j];
        }

        // Final validation: ensure no traversal in result
        for (uint256 k = 0; k + 1 < outLen; k++) {
            require(!(result[k] == 0x2e && result[k+1] == 0x2e), "Traversal detected");
        }

        return string(result);
    }

    /**
     * @notice Batch resolve paths for off-chain proxy consumption
     */
    function batchResolve(bytes32[] calldata entryIds) 
        external view returns (string[] memory paths) 
    {
        paths = new string[](entryIds.length);
        for (uint256 i = 0; i < entryIds.length; i++) {
            if (registry[entryIds[i]].active) {
                paths[i] = registry[entryIds[i]].resolvedPath;
            }
        }
    }
}
